export const sanitizeHtml = (html) => {
    if (!html) return '';

    // Basic escaping for security
    const map = {
        '&': '&amp;',
        '<': '&lt;',
        '>': '&gt;',
        '"': '&quot;',
        "'": '&#039;'
    };

    // First, escape everything
    let escaped = html.replace(/[&<>"']/g, (m) => map[m]);

    // Define the whitelist of allowed tags and their exact attributes as generated by our parser.
    // We use the escaped versions because we are matching against the fully escaped string.
    const allowedTags = [
        { open: '&lt;div class=&quot;flex items-start gap-2 my-1&quot;&gt;', close: '&lt;/div&gt;', replaceOpen: '<div class="flex items-start gap-2 my-1">', replaceClose: '</div>' },
        { open: '&lt;div class=&quot;flex items-start gap-2 my-1 text-slate-600 dark:text-slate-300&quot;&gt;', replaceOpen: '<div class="flex items-start gap-2 my-1 text-slate-600 dark:text-slate-300">' },
        { open: '&lt;span class=&quot;material-symbols-outlined text-emerald-500 text-[16px] mt-0.5&quot;&gt;', close: '&lt;/span&gt;', replaceOpen: '<span class="material-symbols-outlined text-emerald-500 text-[16px] mt-0.5">', replaceClose: '</span>' },
        { open: '&lt;span class=&quot;material-symbols-outlined text-slate-400 text-[16px] mt-0.5&quot;&gt;', replaceOpen: '<span class="material-symbols-outlined text-slate-400 text-[16px] mt-0.5">' },
        { open: '&lt;span class=&quot;text-primary text-[10px] mt-1 mr-1&quot;&gt;', replaceOpen: '<span class="text-primary text-[10px] mt-1 mr-1">' },
        { open: '&lt;span&gt;', replaceOpen: '<span>' },
        { open: '&lt;strong&gt;', close: '&lt;/strong&gt;', replaceOpen: '<strong>', replaceClose: '</strong>' },
        { open: '&lt;em&gt;', close: '&lt;/em&gt;', replaceOpen: '<em>', replaceClose: '</em>' },
        { open: '&lt;blockquote class=&quot;border-l-[3px] border-primary/40 pl-3 my-2 italic text-slate-500 dark:text-slate-400 bg-primary/5 py-1 pr-2 rounded-r-md&quot;&gt;', close: '&lt;/blockquote&gt;', replaceOpen: '<blockquote class="border-l-[3px] border-primary/40 pl-3 my-2 italic text-slate-500 dark:text-slate-400 bg-primary/5 py-1 pr-2 rounded-r-md">', replaceClose: '</blockquote>' },
        { open: '&lt;br( /)?&gt;', replaceOpen: '<br />' },
        { open: '&lt;span class=&quot;material-symbols-outlined text-slate-400 text-[16px] mt-0.5&quot; contenteditable=&quot;false&quot;&gt;', replaceOpen: '<span class="material-symbols-outlined text-slate-400 text-[16px] mt-0.5" contenteditable="false">' },
        { open: '&lt;span contenteditable=&quot;true&quot;&gt;', replaceOpen: '<span contenteditable="true">' }
    ];

    allowedTags.forEach(tag => {
        const escapedOpen = tag.open.includes('(') ? tag.open : tag.open.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        escaped = escaped.replace(new RegExp(escapedOpen, 'g'), tag.replaceOpen);
        if (tag.close) {
            const escapedClose = tag.close.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
            escaped = escaped.replace(new RegExp(escapedClose, 'g'), tag.replaceClose);
        }
    });

    // Special flexible handling for tactical prompt tags
    // These use regex to handle browser variations in attribute spacing and self-closing slashes
    escaped = escaped.replace(/&lt;p\s+class=&quot;prompt-layer&quot;&gt;/g, '<p class="prompt-layer">');
    escaped = escaped.replace(/&lt;\/p&gt;/g, '</p>');
    escaped = escaped.replace(/&lt;br\s+class=&quot;prompt-br&quot;\s*\/?&gt;/g, '<br class="prompt-br"/>');

    // Handle <a> tags separately due to dynamic href.
    // We look for the exact structure generated by parseMarkdown.
    // The regex allows any characters inside the href that are NOT the closing &quot;
    escaped = escaped.replace(/&lt;a href=&quot;((?:(?!&quot;).)*)&quot; target=&quot;_blank&quot; rel=&quot;noopener noreferrer&quot; class=&quot;text-primary hover:underline font-bold&quot;&gt;((?:(?!&lt;\/a&gt;).)*)&lt;\/a&gt;/g, (match, href, content) => {
        // Decode common entities in href for validation
        const decodedHref = href.replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#039;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>');

        // Simple URL validation - allow http, https, and relative paths. Block javascript: etc.
        if (/^(https?:\/\/|\/)/i.test(decodedHref)) {
             return `<a href="${decodedHref}" target="_blank" rel="noopener noreferrer" class="text-primary hover:underline font-bold">${content}</a>`;
        }
        return content; // If invalid URL, return the text content without the link
    });

    return escaped;
};
